(function(){'use strict';const DB='onebox-track-v1';let s={tab:'map',watch:null,active:false,paused:false,start:0,points:[],distance:0,current:null};let map=null,line=null,pin=null,timer=null,leaflet=null;const e=x=>String(x==null?'':x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function open(){return new Promise((ok,no)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('tracks',{keyPath:'id'});r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}async function all(){const d=await open();return new Promise((ok,no)=>{const r=d.transaction('tracks').objectStore('tracks').getAll();r.onsuccess=()=>ok((r.result||[]).sort((a,b)=>b.saved-a.saved));r.onerror=()=>no(r.error)})}async function save(x){const d=await open();return new Promise((ok,no)=>{const t=d.transaction('tracks','readwrite');t.objectStore('tracks').put(x);t.oncomplete=ok;t.onerror=()=>no(t.error)})}async function del(id){const d=await open();return new Promise((ok,no)=>{const t=d.transaction('tracks','readwrite');t.objectStore('tracks').delete(id);t.oncomplete=ok;t.onerror=()=>no(t.error)})}function dist(a,b){const r=n=>n*Math.PI/180,dl=r(b.lat-a.lat),dn=r(b.lng-a.lng),q=Math.sin(dl/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dn/2)**2;return 6371000*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q))}function fmt(n){n=Math.max(0,Math.floor(n/1000));return [Math.floor(n/3600),Math.floor(n%3600/60),n%60].map(x=>String(x).padStart(2,'0')).join(':')}function meters(n){return n>=1000?(n/1000).toFixed(2)+' km':Math.round(n)+' m'}function workspace(){return document.querySelector('#workspace')}function root(){return document.querySelector('[data-track-root]')}function render(){const names={map:'地图',records:'轨迹',feed:'动态',settings:'设置'};return '<section class="track-module" data-track-root><header class="track-head"><div><p>ONERECORD</p><h1>路记</h1><p>把走过的路，留成自己的记录。</p></div><span class="track-badge">轨迹仅本机保存</span></header><nav class="track-tabs">'+Object.keys(names).map(k=>'<button class="track-tab '+(s.tab===k?'active':'')+'" data-tab="'+k+'">'+names[k]+'</button>').join('')+'</nav><div data-body></div></section>'}function body(){if(s.tab==='map')return '<div class="track-panel"><div class="track-row"><div><h2>路线记录</h2><p>记录时保持页面在前台。</p></div><button class="track-button" data-act="locate">定位到我</button></div><div class="track-map" data-map></div><div class="track-stats"><div class="track-stat"><small>用时</small><strong data-time>00:00:00</strong></div><div class="track-stat"><small>距离</small><strong data-distance>0 m</strong></div><div class="track-stat"><small>状态</small><strong data-status>尚未定位</strong></div></div><div class="track-actions">'+(s.active?(s.paused?'<button class="track-button primary" data-act="resume">继续</button>':'<button class="track-button" data-act="pause">暂停</button>')+'<button class="track-button danger" data-act="finish">结束并保存</button>':'<button class="track-button primary" data-act="start">开始记录</button>')+'</div><p class="track-hint">锁屏或切到后台时，浏览器可能暂停定位。原始轨迹只保存在本机。</p></div>';if(s.tab==='records')return '<div class="track-panel"><h2>我的轨迹</h2><p class="track-subtle">轨迹坐标保存在当前设备，可导出 GPX。</p><div class="track-list" data-list>读取中…</div></div>';if(s.tab==='feed')return '<div class="track-panel"><h2>动态</h2><div class="track-alert">动态、登录、评论、点赞和图片需要部署 Cloudflare Worker、D1、R2 后端。当前版本不会上传轨迹点。</div></div>';return '<div class="track-panel"><h2>隐私设置</h2><div class="track-alert">轨迹默认保存在当前设备的 IndexedDB。公开动态应只发布地点名称和文字，不包含精确坐标。可在浏览器设置中撤销定位权限。</div></div>'}function leafletLoad(){if(window.L)return Promise.resolve();if(leaflet)return leaflet;leaflet=new Promise((ok,no)=>{if(!document.querySelector('[data-track-leaflet]')){const l=document.createElement('link');l.rel='stylesheet';l.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';l.dataset.trackLeaflet='';document.head.appendChild(l)}const x=document.createElement('script');x.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';x.onload=ok;x.onerror=()=>no(Error('地图加载失败，请检查网络。'));document.head.appendChild(x)});return leaflet}function mapView(){const el=document.querySelector('[data-map]');if(!el)return;leafletLoad().then(()=>{if(!document.contains(el))return;if(map&&map.getContainer()!==el){map.remove();map=null;line=null;pin=null}if(!map){map=L.map(el).setView([31.23,121.47],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);line=L.polyline([],{color:'#365cf5',weight:5}).addTo(map)}setTimeout(()=>map&&map.invalidateSize(),100);if(s.points.length)line.setLatLngs(s.points.map(p=>[p.lat,p.lng]));if(s.current){if(!pin)pin=L.circleMarker([s.current.lat,s.current.lng],{radius:7,color:'#fff',weight:3,fillColor:'#365cf5',fillOpacity:1}).addTo(map);pin.setLatLng([s.current.lat,s.current.lng])}}).catch(x=>el.textContent=x.message)}function update(){const r=root();if(!r)return;const t=r.querySelector('[data-time]'),d=r.querySelector('[data-distance]'),q=r.querySelector('[data-status]');if(t)t.textContent=fmt((s.active?Date.now():s.start)-s.start);if(d)d.textContent=meters(s.distance);if(q)q.textContent=s.active?(s.paused?'已暂停':'正在记录'):(s.current?'已定位':'尚未定位')}function paint(){const r=root();if(!r)return;r.querySelector('[data-body]').innerHTML=body();if(s.tab==='map')mapView();if(s.tab==='records')records();update()}function stop(){if(s.watch!==null){navigator.geolocation.clearWatch(s.watch);s.watch=null}if(timer){clearInterval(timer);timer=null}}function watch(){stop();s.watch=navigator.geolocation.watchPosition(p=>{if(!s.active||s.paused||p.coords.accuracy>120)return;const x={lat:p.coords.latitude,lng:p.coords.longitude,at:p.timestamp||Date.now()};if(s.points.length){const d=dist(s.points[s.points.length-1],x);if(d<3)return;if(d>150){s.current=x;update();return}s.distance+=d}s.points.push(x);s.current=x;if(line)line.setLatLngs(s.points.map(p=>[p.lat,p.lng]));if(map){if(!pin)pin=L.circleMarker([x.lat,x.lng],{radius:7,color:'#fff',weight:3,fillColor:'#365cf5',fillOpacity:1}).addTo(map);pin.setLatLng([x.lat,x.lng])}update()},x=>{const q=root()?.querySelector('[data-status]');if(q)q.textContent=x.code===1?'请允许定位':'定位信号弱'},{enableHighAccuracy:true,maximumAge:1000,timeout:15000});timer=setInterval(update,1000)}async function records(){const el=document.querySelector('[data-list]');if(!el)return;const xs=await all();el.innerHTML=xs.length?xs.map(x=>'<article class="track-item"><div><strong>'+e(x.name)+'</strong><p>'+new Date(x.start).toLocaleString()+' · '+fmt(x.duration)+' · '+meters(x.distance)+'</p></div><div><button class="track-button" data-export="'+e(x.id)+'">GPX</button> <button class="track-button danger" data-del="'+e(x.id)+'">删除</button></div></article>').join(''):'<div class="track-empty">还没有轨迹记录。</div>'}function exportGpx(x){if(!x)return;const xml='<?xml version="1.0"?><gpx version="1.1" creator="OneBox Track" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>'+e(x.name)+'</name><trkseg>'+x.points.map(p=>'<trkpt lat="'+p.lat+'" lon="'+p.lng+'"><time>'+new Date(p.at).toISOString()+'</time></trkpt>').join('')+'</trkseg></trk></gpx>',a=document.createElement('a');a.href=URL.createObjectURL(new Blob([xml],{type:'application/gpx+xml'}));a.download='onebox-track.gpx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200)}async function act(k){if(k==='start'){if(!navigator.geolocation){alert('浏览器不支持定位');return}s.start=Date.now();s.points=[];s.distance=0;s.active=true;s.paused=false;paint();watch()}else if(k==='pause'){s.paused=true;stop();paint()}else if(k==='resume'){s.paused=false;paint();watch()}else if(k==='finish'){stop();s.active=false;if(s.points.length)await save({id:crypto.randomUUID(),name:'路记 '+new Date(s.start).toLocaleString(),start:s.start,duration:Date.now()-s.start,distance:s.distance,points:s.points,saved:Date.now()});s.points=[];s.current=null;s.start=0;s.distance=0;paint()}else if(k==='locate'){navigator.geolocation.getCurrentPosition(p=>{s.current={lat:p.coords.latitude,lng:p.coords.longitude};s.tab='map';paint();if(map)map.setView([s.current.lat,s.current.lng],16)},x=>alert(x.message),{enableHighAccuracy:true,timeout:15000})}}function show(){const w=workspace();if(!w)return;document.body.dataset.oneboxTrack='true';w.innerHTML=render();paint();document.querySelectorAll('[data-track-entry]').forEach(x=>x.classList.add('active'))}function hide(){document.body.dataset.oneboxTrack='false';document.querySelectorAll('[data-track-entry]').forEach(x=>x.classList.remove('active'));if(s.active){s.active=false;stop()}}function inject(){const nav=document.querySelector('#toolNav');if(!nav||nav.querySelector('[data-track-entry]'))return;const b=document.createElement('button');b.type='button';b.className='track-nav-entry';b.dataset.trackEntry='';b.textContent='路记';nav.appendChild(b)}document.addEventListener('click',async x=>{const entry=x.target.closest('[data-track-entry]');if(entry){x.preventDefault();x.stopImmediatePropagation();history.pushState(null,'','#track');show();return}if(location.hash!=='#track')return;const tab=x.target.closest('[data-tab]');if(tab){s.tab=tab.dataset.tab;paint();return}const a=x.target.closest('[data-act]');if(a){act(a.dataset.act);return}const ex=x.target.closest('[data-export]');if(ex){exportGpx((await all()).find(t=>t.id===ex.dataset.export));return}const d=x.target.closest('[data-del]');if(d&&confirm('删除这条本机轨迹？')){await del(d.dataset.del);records()}} ,true);window.addEventListener('hashchange',x=>{if(location.hash==='#track'){x.stopImmediatePropagation();show()}else if(document.body.dataset.oneboxTrack==='true')hide()},true);window.addEventListener('popstate',()=>{if(location.hash==='#track')show();else hide()});new MutationObserver(inject).observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('DOMContentLoaded',()=>{inject();if(window.__oneboxTrackRequested){history.replaceState(null,'','#track');show()}else if(location.hash==='#track')show()});window.OneBoxTrack={render};})();